from enum import Enum
from typing import Final

TEST_CASE_NAME: Final = "tests.case.name"
"""
The fully qualified human readable name of the [tests case](https://wikipedia.org/wiki/Test_case).
"""

TEST_CASE_RESULT_STATUS: Final = "tests.case.result.status"
"""
The status of the actual tests case result from tests execution.
"""

TEST_SUITE_NAME: Final = "tests.suite.name"
"""
The human readable name of a [tests suite](https://wikipedia.org/wiki/Test_suite).
"""

TEST_SUITE_RUN_STATUS: Final = "tests.suite.run.status"
"""
The status of the tests suite run.
"""


class TestCaseResultStatusValues(Enum):
    PASS = "pass"
    """pass."""
    FAIL = "fail"
    """fail."""


class TestSuiteRunStatusValues(Enum):
    SUCCESS = "success"
    """success."""
    FAILURE = "failure"
    """failure."""
    SKIPPED = "skipped"
    """skipped."""
    ABORTED = "aborted"
    """aborted."""
    TIMED_OUT = "timed_out"
    """timed_out."""
    IN_PROGRESS = "in_progress"
    """in_progress."""
